fn solve(x: i32) -> i32 {
    // Convert x to string to extract its digit and length
    let s = x.to_string();
    let k = s.len() as i32;
    let d = s.chars().next().unwrap().to_digit(10).unwrap() as i32;

    // All numbers with digits less than d contribute 1+2+3+4 = 10 presses each
    // For the digit d itself, we press 1 time for "d", 2 times for "dd", ..., k times for the given x
    // Sum of 1..k is k*(k+1)/2
    (d - 1) * 10 + k * (k + 1) / 2
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn example_cases() {
        // For x = 1 -> only "1" requires 1 press
        assert_eq!(solve(1), 1);

        // For x = 11 -> "1" (1 press) + "11" (2 presses) = 3
        assert_eq!(solve(11), 3);

        // For x = 111 -> 1 + 2 + 3 = 6
        assert_eq!(solve(111), 6);

        // For x = 22 -> numbers are:
        //   1, 11, 111, 1111 (total 10 presses)
        //   2 (1 press), 22 (2 presses) = 3 presses
        // total = 10 + 3 = 13
        assert_eq!(solve(22), 13);

        // For x = 4444 -> previous digits 1,2,3 each give 10 presses = 30
        // plus 1+2+3+4 = 10 presses for digit 4 = 40
        assert_eq!(solve(4444), 40);
    }
}